import { useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Loader2, Sparkles } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";

type Props = {
  summary?: string | null;
  generatedAt?: string | null;
  model?: string | null;
  title?: string;
  triggerLabel?: string;
  className?: string;
  itemId?: string;
  onGenerated?: (summary: string, model: string, generatedAt: string) => void;
};

function fmt(iso?: string | null) {
  if (!iso) return null;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString();
}

export function AISummaryDialog({
  summary: initialSummary,
  generatedAt: initialGeneratedAt,
  model: initialModel,
  title = "AI Summary",
  triggerLabel = "AI Summary",
  className,
  itemId,
  onGenerated,
}: Props) {
  const [open, setOpen] = useState(false);
  const [summary, setSummary] = useState(initialSummary);
  const [generatedAt, setGeneratedAt] = useState(initialGeneratedAt);
  const [model, setModel] = useState(initialModel);
  const [generating, setGenerating] = useState(false);
  const [genError, setGenError] = useState<string | null>(null);

  const meta = useMemo(() => {
    const bits: string[] = [];
    if (generatedAt) bits.push(`Generated: ${fmt(generatedAt)}`);
    if (model) bits.push(`Model: ${model}`);
    return bits;
  }, [generatedAt, model]);

  async function handleGenerate() {
    if (!itemId) return;
    setGenerating(true);
    setGenError(null);
    try {
      const { data, error } = await supabase.functions.invoke("ai-brief", {
        body: { ids: [itemId], force: true },
      });
      if (error) throw new Error(error.message);
      // Fetch the updated record from DB to get the generated summary
      const { data: row, error: fetchErr } = await supabase
        .from("threat_items")
        .select("ai_summary,ai_summary_model,ai_summary_generated_at")
        .eq("id", itemId)
        .single();
      if (fetchErr) throw new Error(fetchErr.message);
      if (row?.ai_summary) {
        setSummary(row.ai_summary);
        setModel(row.ai_summary_model ?? null);
        setGeneratedAt(row.ai_summary_generated_at ?? null);
        onGenerated?.(row.ai_summary, row.ai_summary_model ?? "", row.ai_summary_generated_at ?? "");
      } else {
        setGenError("Brief generation completed but no summary was returned.");
      }
    } catch (e: any) {
      setGenError(e?.message ?? "Generation failed. Try again.");
    } finally {
      setGenerating(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" variant="outline" className={className}>
          <Sparkles className="h-3.5 w-3.5 mr-2 text-primary" />
          {triggerLabel}
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-4 w-4 text-primary" />
            {title}
            <Badge variant="outline" className="ml-2 text-[10px] text-muted-foreground">
              {summary ? "stored" : "not generated"}
            </Badge>
          </DialogTitle>
        </DialogHeader>
        {meta.length > 0 && (
          <div className="text-xs text-muted-foreground">{meta.join(" · ")}</div>
        )}
        {/* Legal disclaimer — required for compliance */}
        <div className="text-[10px] text-muted-foreground/60 border-b border-border/30 pb-2 mb-2">
          AI-generated summary derived from public intelligence sources. Verify independently before taking action.
        </div>
        {summary ? (
          <div className="space-y-3">
            <div className="whitespace-pre-wrap text-sm leading-relaxed text-foreground/90 max-h-[60vh] overflow-auto rounded-md border border-border/60 bg-muted/20 p-3">
              {summary}
            </div>
            {itemId && (
              <Button size="sm" variant="outline" onClick={handleGenerate} disabled={generating} className="gap-2">
                {generating ? <><Loader2 className="h-3.5 w-3.5 animate-spin" /> Regenerating…</> : <><Sparkles className="h-3.5 w-3.5" /> Regenerate from live sources</>}
              </Button>
            )}
            {genError && <p className="text-xs text-destructive">{genError}</p>}
          </div>
        ) : (
          <div className="rounded-md border border-border/60 bg-muted/20 p-4 space-y-3">
            <p className="text-sm text-muted-foreground">
              No stored AI summary yet.{" "}
              {itemId
                ? "Generate one now using the AI Brief engine."
                : "It will appear automatically after the scheduled summarizer runs."}
            </p>
            {itemId && (
              <Button
                size="sm"
                onClick={handleGenerate}
                disabled={generating}
                className="gap-2"
              >
                {generating ? (
                  <><Loader2 className="h-3.5 w-3.5 animate-spin" /> Generating…</>
                ) : (
                  <><Sparkles className="h-3.5 w-3.5" /> Generate AI Brief</>
                )}
              </Button>
            )}
            {genError && (
              <p className="text-xs text-destructive">{genError}</p>
            )}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}
